<script setup>
import { onUnmounted,ref } from 'vue'; import { ElMessage } from 'element-plus'; import { managerApi,managerEvents,pipelineApi } from '../shared/api';
const configuredMode=import.meta.env.VITE_ORCHESTRATION_MODE==='platform'?'platform':'local';
const mode=ref(localStorage.getItem('agent-console.last-run-mode')??configuredMode),runId=ref(localStorage.getItem('agent-console.last-run-id')??''),clientCode=ref(''),roomId=ref(''),spec=ref('请 Team Leader 按 P1 开始处理当前向导需求。'),run=ref(null),approvalId=ref(''),busy=ref(false);
let stream=null;onUnmounted(()=>stream?.abort());
async function create(){busy.value=true;try{localStorage.setItem('agent-console.mode',mode.value);if(mode.value==='platform'){run.value=await managerApi.create({client_code:clientCode.value,room_id:roomId.value||undefined,spec:spec.value});runId.value=run.value.run_id;startStream();}else{throw new Error('local 模式请在向导中点击「开始生成」，确保提交的是权威 Phase1Result');}}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function refresh(){try{const data=mode.value==='platform'?await managerApi.get(runId.value):await pipelineApi.get(runId.value);run.value=mode.value==='platform'?data:{...data.run,run_id:data.run.run_id,planner:'local',build_path:data.run.build_path,artifacts:data.artifacts.map(a=>({kind:a.kind,state:'v'+a.version,at:a.created_at,detail:a.written_by})),events:data.artifacts.map((a,index)=>({id:index+1,type:'artifact',at:a.created_at,data:{kind:a.kind,version:a.version}}))};const pending=mode.value==='platform'?run.value.pending_approvals??[]:data.artifacts.filter(a=>a.kind==='approval'&&a.payload?.status==='PENDING').map(a=>a.payload.approval_id);const latest=mode.value==='platform'?pending:data.artifacts.filter(a=>a.kind==='approval').map(a=>a.payload?.approval_id).filter(Boolean);if(!approvalId.value)approvalId.value=(pending.at?.(-1)??pending[pending.length-1])||(latest.at?.(-1)??latest[latest.length-1])||''}catch(e){ElMessage.error(e.message)}}
async function decide(approved){try{const body={approval_id:approvalId.value,approved};if(mode.value==='platform')await managerApi.approve(runId.value,body);else await pipelineApi.approve(runId.value,body);await refresh();ElMessage.success(approved?'已批准':'已拒绝')}catch(e){ElMessage.error(e.message)}}
function startStream(){if(mode.value!=='platform'||!runId.value)return;stream?.abort();stream=new AbortController();managerEvents(runId.value,(type,event)=>{if(!run.value)run.value={run_id:runId.value,events:[],artifacts:[]};if(!(run.value.events??=[]).some(item=>item.id===event.id))run.value.events.push(event);if(type==='approval_required'&&!approvalId.value)approvalId.value=event.data?.approval_id??'';if(type==='done')refresh();},stream.signal).catch(error=>{if(error.name!=='AbortError')ElMessage.warning('事件流已断开：'+error.message)});}
</script>
<template><section class="page"><div class="page-title"><div><h2>编排看板</h2><p>排障视图：run / artifact 时间线与审批重放。业务发布请在「搭建向导」里确认。</p></div><el-segmented v-model="mode" :options="['platform','local']"/></div><el-card><el-form label-position="top"><el-form-item label="client_code（仅 manager 控制面发号使用）"><el-input v-model="clientCode"/></el-form-item><el-form-item label="Leader Room（空则用服务端默认）"><el-input v-model="roomId"/></el-form-item><el-form-item label="P1 spec"><el-input v-model="spec" type="textarea" :rows="4"/></el-form-item><el-button type="primary" :loading="busy" @click="create">开始编排</el-button></el-form></el-card><el-card class="gap"><div class="lookup"><el-input v-model="runId" placeholder="run_id"/><el-button @click="refresh">刷新</el-button></div><template v-if="run"><el-descriptions :column="3" border><el-descriptions-item label="run_id">{{run.run_id}}</el-descriptions-item><el-descriptions-item label="状态">{{run.status}}</el-descriptions-item><el-descriptions-item label="planner">{{run.planner}}</el-descriptions-item><el-descriptions-item label="build_path">{{run.build_path || '—'}}</el-descriptions-item></el-descriptions><h3>Artifact 时间线</h3><el-timeline><el-timeline-item v-for="artifact in run.artifacts" :key="artifact.kind" :timestamp="artifact.at" placement="top"><b>{{artifact.kind}}</b> · {{artifact.state}}<p>{{artifact.detail}}</p></el-timeline-item></el-timeline><h3>编排事件</h3><el-timeline class="timeline"><el-timeline-item v-for="event in run.events" :key="event.id" :timestamp="event.at" placement="top"><b>{{event.type}}</b><pre>{{JSON.stringify(event.data,null,2)}}</pre></el-timeline-item></el-timeline></template></el-card><el-card class="gap"><h3>Human 审批</h3><div class="lookup"><el-input v-model="approvalId" placeholder="approval_id"/><el-button type="success" @click="decide(true)">批准</el-button><el-button type="danger" @click="decide(false)">拒绝</el-button></div></el-card></section></template>
